import React from 'react';

// Center button is always "home/new thought" — large dark circle
// Left = Log, Right = Breathe (secondary actions, smaller light circles)
// Day (checkin) is accessed via the center or from within the app

const SIDE_TABS = [
  {
    id: 'history',
    label: 'LOG',
    icon: (
      <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
        <rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>
      </svg>
    ),
  },
  {
    id: 'breathing',
    label: 'BREATHE',
    icon: (
      <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 4c0 0-4 3-4 7s4 5 4 9"/><path d="M12 4c0 0 4 3 4 7s-4 5-4 9"/>
      </svg>
    ),
  },
];

export default function Nav({ page, setPage, onNewThought }) {
  return (
    <div style={{
      position: 'fixed',
      bottom: 36,
      left: '50%',
      transform: 'translateX(-50%)',
      zIndex: 300,
      display: 'flex',
      alignItems: 'flex-end',
      gap: 20,
    }}>
      {/* LEFT — Log */}
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }}>
        <button
          onClick={() => setPage('history')}
          style={{
            width: 56, height: 56, borderRadius: '50%',
            background: page === 'history' ? '#1A2A2A' : 'rgba(238,234,227,0.12)',
            border: 'none', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: page === 'history' ? '#EEEAE3' : 'rgba(238,234,227,0.4)',
            transition: 'all 0.25s cubic-bezier(0.34,1.3,0.64,1)',
            boxShadow: page === 'history' ? '0 4px 20px rgba(0,0,0,0.35)' : '0 2px 8px rgba(0,0,0,0.2)',
            WebkitTapHighlightColor: 'transparent',
          }}
        >
          {SIDE_TABS[0].icon}
        </button>
        <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: '0.1em', color: page === 'history' ? 'rgba(238,234,227,0.7)' : 'rgba(238,234,227,0.25)', fontFamily: "'Inter', sans-serif", whiteSpace: 'nowrap' }}>
          {SIDE_TABS[0].label}
        </span>
      </div>

      {/* CENTER — large dark, Home + new thought trigger */}
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8, marginBottom: 8 }}>
        <button
          onClick={() => page === 'home' ? onNewThought?.() : setPage('home')}
          style={{
            width: 72, height: 72, borderRadius: '50%',
            background: '#1A2A2A',
            border: 'none', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            boxShadow: '0 6px 28px rgba(0,0,0,0.4), 0 2px 8px rgba(0,0,0,0.25)',
            transition: 'transform 0.2s cubic-bezier(0.34,1.4,0.64,1)',
            WebkitTapHighlightColor: 'transparent',
          }}
          onMouseDown={e => e.currentTarget.style.transform = 'scale(0.94)'}
          onMouseUp={e => e.currentTarget.style.transform = 'scale(1)'}
          onTouchStart={e => e.currentTarget.style.transform = 'scale(0.94)'}
          onTouchEnd={e => e.currentTarget.style.transform = 'scale(1)'}
        >
          <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="rgba(238,234,227,0.9)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 5v14M5 12h14"/>
          </svg>
        </button>
        <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: '0.1em', color: 'rgba(238,234,227,0.55)', fontFamily: "'Inter', sans-serif", whiteSpace: 'nowrap' }}>
          NEW THOUGHT
        </span>
      </div>

      {/* RIGHT — Breathe */}
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }}>
        <button
          onClick={() => setPage('breathing')}
          style={{
            width: 56, height: 56, borderRadius: '50%',
            background: page === 'breathing' ? '#1A2A2A' : 'rgba(238,234,227,0.12)',
            border: 'none', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: page === 'breathing' ? '#EEEAE3' : 'rgba(238,234,227,0.4)',
            transition: 'all 0.25s cubic-bezier(0.34,1.3,0.64,1)',
            boxShadow: page === 'breathing' ? '0 4px 20px rgba(0,0,0,0.35)' : '0 2px 8px rgba(0,0,0,0.2)',
            WebkitTapHighlightColor: 'transparent',
          }}
        >
          {SIDE_TABS[1].icon}
        </button>
        <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: '0.1em', color: page === 'breathing' ? 'rgba(238,234,227,0.7)' : 'rgba(238,234,227,0.25)', fontFamily: "'Inter', sans-serif", whiteSpace: 'nowrap' }}>
          {SIDE_TABS[1].label}
        </span>
      </div>
    </div>
  );
}
